mapper.select:
select id, mes_id, material_code, material_name, erp_code, sap_material_code, valid_date, material_group, minpark_time, major_type, glue_type, is_high_consumption, remark, del_flag, create_by, create_time, update_by, update_time from t_mes_bas_material
del_flag = '0' and instr(material_code,#{materialCode}) > 0 and INSTR(material_name, #{materialName}) > 0 and erp_code = #{erpCode} and sap_material_code = #{sapMaterialCode}
and valid_date = #{validDate} and material_group = #{materialGroup} and major_type = #{majorType} and glue_type = #{glueType} and glue_type is null and is_high_consumption = #{isHighConsumption}
order by create_time desc
order by ${orderStr}

WITH temp_table AS (
SELECT #{rowNumber}+2 row_numbers, #{data.materialCode} material_code
) select #{importLogId} importLogId, t.row_numbers errorRow, #{errorDetail} errorDetail, #{createBy} createBy, now() createTime from t_mes_bas_material m inner join temp_table t on m.material_code = t.material_code and m.del_flag ='0'

mapper.insert:
insert into t_mes_bas_material ( id, mes_id, material_code, material_name, erp_code, sap_material_code, valid_date,material_group, minpark_time, major_type, glue_type, is_high_consumption, remark, del_flag, create_by, create_time, update_by, update_time ) select NULL id, x.* from (
select #{mesBasMaterial.mesId,jdbcType=DOUBLE} mes_id, #{mesBasMaterial.materialCode,jdbcType= VARCHAR} material_code, #{mesBasMaterial.materialName,jdbcType= VARCHAR} material_name, #{mesBasMaterial.erpCode,jdbcType= VARCHAR} erp_code, #{mesBasMaterial.sapMaterialCode,jdbcType= VARCHAR} sap_material_code, #{mesBasMaterial.validDate,jdbcType=DOUBLE} valid_date, #{mesBasMaterial.materialGroup,jdbcType=VARCHAR} material_group, #{mesBasMaterial.minparkTime,jdbcType=DOUBLE} minpark_time, #{mesBasMaterial.majorType,jdbcType=VARCHAR} major_type, #{mesBasMaterial.glueType,jdbcType= VARCHAR} glue_type, #{mesBasMaterial.isHighConsumption,jdbcType= VARCHAR} is_high_consumption, #{mesBasMaterial.remark,jdbcType= VARCHAR} remark, #{mesBasMaterial.delFlag,jdbcType= VARCHAR} del_flag, #{mesBasMaterial.createBy,jdbcType= VARCHAR} create_by, #{mesBasMaterial.createTime,jdbcType=TIMESTAMP} create_time, #{mesBasMaterial.updateBy,jdbcType= VARCHAR} update_by, #{mesBasMaterial.updateTime,jdbcType=TIMESTAMP} update_time
) x
